import{I as t,o as l,c as r,b6 as n,J as o,w as u,j as e,a as p}from"./chunks/framework.BUXTSoD9.js";const v=JSON.parse(`{"title":"The Mom Test : comment valider les besoins par les entretiens utilisateurs","description":"Article d'introduction à The Mom Test pour les lecteurs débutants. Apprenez à éviter les retours de politesse, à mener des entretiens utilisateurs axés sur les comportements réels, les faits concrets et les problèmes existants, et à transformer les « ça a l'air pas mal » en jugements de besoins plus fiables.","frontmatter":{"title":"The Mom Test : comment valider les besoins par les entretiens utilisateurs","description":"Article d'introduction à The Mom Test pour les lecteurs débutants. Apprenez à éviter les retours de politesse, à mener des entretiens utilisateurs axés sur les comportements réels, les faits concrets et les problèmes existants, et à transformer les « ça a l'air pas mal » en jugements de besoins plus fiables."},"headers":[],"relativePath":"fr-fr/stage-1/appendix-mom-test/index.md","filePath":"fr-fr/stage-1/appendix-mom-test/index.md"}`),d={name:"fr-fr/stage-1/appendix-mom-test/index.md"},b=Object.assign(d,{setup(c){const a="Environ <strong>1,5 heure</strong>";return(m,s)=>{const i=t("ChapterIntroduction");return l(),r("div",null,[s[1]||(s[1]=n('<h1 id="the-mom-test-comment-valider-les-besoins-par-les-entretiens-utilisateurs" tabindex="-1">The Mom Test : comment valider les besoins par les entretiens utilisateurs <a class="header-anchor" href="#the-mom-test-comment-valider-les-besoins-par-les-entretiens-utilisateurs" aria-label="Permalink to “The Mom Test : comment valider les besoins par les entretiens utilisateurs”">​</a></h1><p><a id="top-mom"></a></p><h2 id="introduction-du-chapitre" tabindex="-1">Introduction du chapitre <a class="header-anchor" href="#introduction-du-chapitre" aria-label="Permalink to “Introduction du chapitre”">​</a></h2>',3)),o(i,{duration:a,tags:["Entretien utilisateur","Validation des besoins","Recherche utilisateur","Étude de marché"],coreOutput:"1 ensemble de questions d'entretien plus à même de révéler des informations réelles",expectedOutput:"Ne plus prendre les encouragements de politesse pour une validation, et savoir juger la direction à partir de comportements réels"},{default:u(()=>[...s[0]||(s[0]=[e("p",null,"Beaucoup de gens, lorsqu'ils font leur première étude de marché, pensent que le plus important est de « discuter avec des gens ». Alors ils vont demander à leurs amis, collègues, voire leur famille :",-1),e("ul",null,[e("li",null,"Tu penses quoi de mon idée ?"),e("li",null,"S'il y avait un produit comme ça, tu l'utiliserais ?"),e("li",null,"Cette fonctionnalité, ça a l'air pas mal, non ?")],-1),e("p",null,"L'autre personne donne souvent un retour très encourageant :",-1),e("ul",null,[e("li",null,"C'est pas mal"),e("li",null,"Ça a l'air utile"),e("li",null,"Je pense que tu devrais essayer")],-1),e("p",null,"Le problème, c'est que ces réponses ne vous aident généralement pas à prendre une décision. Elles ressemblent davantage à de la politesse, du soutien, ou une réaction naturelle pour ne pas vous décevoir sur le moment. Vous pensez avoir obtenu une « validation de marché », mais en réalité vous n'avez collecté qu'un ensemble de réconforts difficilement exploitables pour la prise de décision.",-1),e("p",null,[p("La méthode The Mom Test a été conçue précisément pour résoudre ce problème. Elle nous rappelle : "),e("strong",null,"ce n'est pas que les utilisateurs essaient de vous mentir, c'est que votre façon de poser les questions oriente naturellement l'autre personne vers des réponses flatteuses mais inutiles.")],-1)])]),_:1}),s[2]||(s[2]=n(`<div class="info custom-block"><p class="custom-block-title">SOP minimale</p><p><strong>Objectif</strong> : après avoir lu, vous saurez mieux comment discuter avec les utilisateurs pour ne pas entendre uniquement « ça a l&#39;air pas mal », mais vraiment obtenir des informations qui vous aident à juger la direction.</p><p><strong>Actions</strong> : réécrivez vos 5 questions initiales, en privilégiant « quand est la dernière fois que ça s&#39;est produit » et « comment avez-vous géré ça à ce moment-là ».</p><p><strong>Résultat</strong> : vous saurez plus facilement distinguer ce qui est une opinion de ce qui constitue une véritable preuve pour étayer vos décisions.</p><p><strong>Navigation rapide</strong> : <a href="#mom-what">Qu&#39;est-ce que The Mom Test</a> · <a href="#mom-principles">Trois principes fondamentaux</a> · <a href="#mom-ai">Comment l&#39;IA peut vous aider</a></p></div><h2 id="ce-que-vous-apprendrez" tabindex="-1">Ce que vous apprendrez <a class="header-anchor" href="#ce-que-vous-apprendrez" aria-label="Permalink to “Ce que vous apprendrez”">​</a></h2><ol><li>Quel problème The Mom Test résout réellement, et pourquoi beaucoup de « recherches utilisateurs » ne capturent en fait pas d&#39;informations réelles</li><li>Les principes fondamentaux de cette méthode : moins demander des opinions, plus demander des comportements ; moins demander des hypothèses, plus demander des faits</li><li>Comment transformer une question qui génère facilement des faux positifs en une question d&#39;entretien plus précieuse</li><li>Comment combiner The Mom Test avec JTBD, la validation des besoins et l&#39;évaluation du MVP</li></ol><p><a id="mom-what"></a></p><h2 id="_1-qu-est-ce-que-the-mom-test-vraiment" tabindex="-1"><a href="#top-mom">1. Qu&#39;est-ce que The Mom Test vraiment</a> <a class="header-anchor" href="#_1-qu-est-ce-que-the-mom-test-vraiment" aria-label="Permalink to “1. Qu&#39;est-ce que The Mom Test vraiment”">​</a></h2><p>The Mom Test vient du livre du même nom de Rob Fitzpatrick. Son nom ressemble à une blague, mais il touche juste :</p><p><strong>Même votre maman aurait du mal à vous dire directement « c&#39;est une mauvaise idée ».</strong></p><p>La raison n&#39;est pas qu&#39;elle est malhonnête, mais :</p><ul><li>Elle ne veut pas vous blesser</li><li>Elle va instinctivement vous encourager</li><li>Elle a facilement tendance à répondre dans le sens de ce que vous exprimez</li></ul><p>Et ce n&#39;est pas seulement votre maman — les amis, collègues, anciens camarades de classe, et même beaucoup d&#39;inconnus, face à votre idée de produit, donnent souvent des « retours positifs » similaires. Cela ne signifie pas que le besoin est réel, seulement que vous avez formulé votre question d&#39;une manière qui génère facilement des réponses flatteuses.</p><p>Donc, l&#39;essentiel de The Mom Test n&#39;a jamais été « ne demandez pas à votre maman », mais :</p><p><strong>Ne formulez pas vos questions de façon à ce que n&#39;importe qui soit enclin à vous donner une réponse qui vous va droit au cœur.</strong></p><p>Ce que cette méthode veut vraiment vous apprendre, c&#39;est comment obtenir, par la conversation, des informations plus proches des besoins réels, plutôt que de collecter un ensemble de commentaires qui vous font simplement vous sentir bien.</p><h2 id="_2-quel-est-le-probleme-fondamental-qu-elle-resout" tabindex="-1">2. Quel est le problème fondamental qu&#39;elle résout <a class="header-anchor" href="#_2-quel-est-le-probleme-fondamental-qu-elle-resout" aria-label="Permalink to “2. Quel est le problème fondamental qu&#39;elle résout”">​</a></h2><p>The Mom Test résout principalement une illusion cognitive très courante :</p><p><strong>Prendre les retours positifs de politesse pour des besoins réels.</strong></p><p>Par exemple, si vous demandez :</p><ul><li>Tu penses quoi de cette idée d&#39;application ?</li><li>Si je faisais un outil AI pour t&#39;aider à écrire ton CV, tu l&#39;utiliserais ?</li><li>Cette fonctionnalité, est-ce qu&#39;elle a de la valeur ?</li></ul><p>Ces questions ont en commun :</p><ul><li>Elles demandent toutes des « opinions »</li><li>Elles portent toutes une pointe de suggestion</li><li>Elles parlent toutes d&#39;un futur qui n&#39;est pas encore arrivé</li></ul><p>Or, les réponses des gens aux « opinions » et aux « hypothèses futures » sont généralement instables. Beaucoup de gens surestiment leur intérêt, leur capacité d&#39;exécution, et leur volonté future de payer.</p><p>The Mom Test vous rappelle donc :</p><ul><li>Ne croyez pas trop les évaluations des autres sur vos idées</li><li>Ne croyez pas trop les prédictions des autres sur leurs comportements futurs</li><li>Revenez autant que possible aux comportements réels déjà observés chez les utilisateurs</li></ul><p>Parce que comparé à « est-ce que tu utiliserais ça », « comment as-tu géré ce problème la dernière fois » est souvent bien plus proche de la vérité.</p><p><a id="mom-principles"></a></p><h2 id="_3-les-trois-principes-fondamentaux" tabindex="-1"><a href="#top-mom">3. Les trois principes fondamentaux</a> <a class="header-anchor" href="#_3-les-trois-principes-fondamentaux" aria-label="Permalink to “3. Les trois principes fondamentaux”">​</a></h2><p>Si vous ne deviez retenir que la partie la plus importante, commencez par ces trois principes.</p><h3 id="_3-1-parlez-moins-de-votre-idee-parlez-plus-des-experiences-reelles-passees-de-l-utilisateur" tabindex="-1">3.1 Parlez moins de votre idée, parlez plus des expériences réelles passées de l&#39;utilisateur <a class="header-anchor" href="#_3-1-parlez-moins-de-votre-idee-parlez-plus-des-experiences-reelles-passees-de-l-utilisateur" aria-label="Permalink to “3.1 Parlez moins de votre idée, parlez plus des expériences réelles passées de l&#39;utilisateur”">​</a></h3><p>Beaucoup d&#39;entretiens inefficaces commencent par exposer sa propre solution, à quel point on est enthousiaste, quel produit on prépare. Le problème, c&#39;est qu&#39;une fois que vous avez trop parlé, l&#39;autre personne passe facilement en mode « vous accompagner » et « vous encourager ».</p><p>Une meilleure approche consiste à se concentrer sur l&#39;expérience de l&#39;autre :</p><ul><li>Quand est la dernière fois que vous avez rencontré ce problème ?</li><li>Que faisiez-vous à ce moment-là ?</li><li>Comment avez-vous fini par le résoudre ?</li><li>Quelle étape était la plus pénible ?</li></ul><p>Ce type de questions ramène naturellement la conversation vers la réalité, au lieu de rester sur des préférences imaginaires.</p><h3 id="_3-2-demandez-moins-d-opinions-abstraites-demandez-plus-de-faits-concrets" tabindex="-1">3.2 Demandez moins d&#39;opinions abstraites, demandez plus de faits concrets <a class="header-anchor" href="#_3-2-demandez-moins-d-opinions-abstraites-demandez-plus-de-faits-concrets" aria-label="Permalink to “3.2 Demandez moins d&#39;opinions abstraites, demandez plus de faits concrets”">​</a></h3><p>« Je trouve cette fonctionnalité pas mal », « ça a l&#39;air bien », « ça semble utile » — toutes ces expressions sont trop abstraites pour guider les décisions produit.</p><p>Les informations plus précieuses ressemblent plutôt à ça :</p><ul><li>La semaine dernière, j&#39;ai passé 2 heures à me débattre avec ce problème</li><li>Actuellement, je me débrouille avec Excel et WeChat</li><li>Le mois dernier, j&#39;ai déjà payé pour un outil similaire</li><li>Ma plus grande crainte est de me tromper, pas d&#39;être lent</li></ul><p>Ce sont ces informations qui vous aident vraiment à juger l&#39;intensité du problème, sa fréquence et la probabilité de paiement.</p><h3 id="_3-3-demandez-moins-aux-utilisateurs-quelle-solution-ils-veulent-observez-davantage-comment-ils-resolvent-le-probleme-actuellement" tabindex="-1">3.3 Demandez moins aux utilisateurs quelle solution ils veulent, observez davantage comment ils résolvent le problème actuellement <a class="header-anchor" href="#_3-3-demandez-moins-aux-utilisateurs-quelle-solution-ils-veulent-observez-davantage-comment-ils-resolvent-le-probleme-actuellement" aria-label="Permalink to “3.3 Demandez moins aux utilisateurs quelle solution ils veulent, observez davantage comment ils résolvent le problème actuellement”">​</a></h3><p>Les utilisateurs sont très doués pour décrire leurs frustrations, mais pas nécessairement pour concevoir des solutions.</p><p>Si vous demandez :</p><ul><li>Voudriez-vous un AI qui fait ça automatiquement pour vous ?</li><li>Pensez-vous qu&#39;ajouter une fonctionnalité intelligente serait utile ?</li></ul><p>Vous n&#39;obtiendrez généralement qu&#39;une attitude vague envers une solution, pas le besoin lui-même.</p><p>Les meilleures questions sont :</p><ul><li>Comment gérez-vous ce problème actuellement ?</li><li>Pourquoi avez-vous choisi cette méthode ?</li><li>Qu&#39;est-ce qui ne va pas avec cette méthode ?</li></ul><p>Comprendre les alternatives actuelles est souvent plus important que de demander directement « que voulez-vous ».</p><h2 id="_4-pourquoi-les-gens-vous-donnent-toujours-des-reponses-flatteuses-mais-inutiles" tabindex="-1">4. Pourquoi les gens vous donnent toujours des réponses flatteuses mais inutiles <a class="header-anchor" href="#_4-pourquoi-les-gens-vous-donnent-toujours-des-reponses-flatteuses-mais-inutiles" aria-label="Permalink to “4. Pourquoi les gens vous donnent toujours des réponses flatteuses mais inutiles”">​</a></h2><p>Si vous comprenez cela, vous ferez beaucoup moins d&#39;erreurs de jugement lors des entretiens.</p><h3 id="_4-1-les-gens-sont-instinctivement-polis" tabindex="-1">4.1 Les gens sont instinctivement polis <a class="header-anchor" href="#_4-1-les-gens-sont-instinctivement-polis" aria-label="Permalink to “4.1 Les gens sont instinctivement polis”">​</a></h3><p>Surtout quand votre interlocuteur a une relation avec vous, il aura du mal à dire directement :</p><ul><li>Cette direction ne me semble pas viable</li><li>Je n&#39;utiliserais pas ça du tout</li><li>Ce problème n&#39;est pas si important pour moi</li></ul><p>Il dira plus probablement « c&#39;est pas mal » ou « ça vaut le coup d&#39;essayer ».</p><h3 id="_4-2-les-gens-surestiment-leur-futur-moi" tabindex="-1">4.2 Les gens surestiment leur futur moi <a class="header-anchor" href="#_4-2-les-gens-surestiment-leur-futur-moi" aria-label="Permalink to “4.2 Les gens surestiment leur futur moi”">​</a></h3><p>Beaucoup de gens croient sincèrement qu&#39;ils seront à l&#39;avenir :</p><ul><li>Plus disciplinés</li><li>Plus disposés à apprendre</li><li>Plus disposés à payer</li><li>Plus ouverts aux nouveaux outils</li></ul><p>Donc la phrase « si ça existait, je l&#39;utiliserais probablement » ne signifie souvent pas que la personne l&#39;utilisera vraiment.</p><h3 id="_4-3-votre-facon-de-poser-les-questions-oriente-les-reponses" tabindex="-1">4.3 Votre façon de poser les questions oriente les réponses <a class="header-anchor" href="#_4-3-votre-facon-de-poser-les-questions-oriente-les-reponses" aria-label="Permalink to “4.3 Votre façon de poser les questions oriente les réponses”">​</a></h3><p>Quand vous demandez :</p><ul><li>Mon idée est pas mal, non ?</li><li>Cette fonctionnalité vous serait très utile, n&#39;est-ce pas ?</li></ul><p>Vous avez subtilement glissé la « bonne réponse » dans la question.</p><p>C&#39;est pourquoi The Mom Test insiste particulièrement : <strong>ne transformez pas vos entretiens en quête de validation.</strong></p><h2 id="_5-comparaison-directe-quelles-questions-sont-inutiles-lesquelles-sont-plus-precieuses" tabindex="-1">5. Comparaison directe : quelles questions sont inutiles, lesquelles sont plus précieuses <a class="header-anchor" href="#_5-comparaison-directe-quelles-questions-sont-inutiles-lesquelles-sont-plus-precieuses" aria-label="Permalink to “5. Comparaison directe : quelles questions sont inutiles, lesquelles sont plus précieuses”">​</a></h2><p>Ces comparaisons sont utiles pour presque tous les débutants.</p><table tabindex="0"><thead><tr><th>Questions inutiles</th><th>Questions plus précieuses</th></tr></thead><tbody><tr><td>Tu penses quoi de mon idée ?</td><td>Quand est la dernière fois que tu as rencontré ce problème ?</td></tr><tr><td>S&#39;il y avait ce produit, tu l&#39;utiliserais ?</td><td>Comment gérez-vous ce problème actuellement ?</td></tr><tr><td>Serais-tu prêt à payer pour cette fonctionnalité ?</td><td>As-tu déjà dépensé de l&#39;argent pour ce problème ? Pour quoi ?</td></tr><tr><td>Trouves-tu cette fonctionnalité importante ?</td><td>Dans ce processus, quelle étape est la plus pénible, la plus lente, la plus angoissante ?</td></tr><tr><td>Voudrais-tu un AI qui fait ça automatiquement ?</td><td>Pourquoi n&#39;as-tu pas encore trouvé de meilleure solution ?</td></tr></tbody></table><p>Ce qui est le plus important dans ce tableau, ce ne sont pas les phrases exactes, mais la direction sous-jacente :</p><ul><li>Des opinions vers les faits</li><li>Du futur vers le passé</li><li>De votre solution vers le problème de l&#39;utilisateur</li></ul><h2 id="_6-un-rythme-d-entretien-que-meme-un-debutant-peut-utiliser-immediatement" tabindex="-1">6. Un rythme d&#39;entretien que même un débutant peut utiliser immédiatement <a class="header-anchor" href="#_6-un-rythme-d-entretien-que-meme-un-debutant-peut-utiliser-immediatement" aria-label="Permalink to “6. Un rythme d&#39;entretien que même un débutant peut utiliser immédiatement”">​</a></h2><p>Si vous voulez aller parler à des gens dès maintenant, vous pouvez suivre cet ordre.</p><h3 id="_6-1-ouverture-expliquez-que-vous-apprenez-pas-que-vous-vendez" tabindex="-1">6.1 Ouverture : expliquez que vous apprenez, pas que vous vendez <a class="header-anchor" href="#_6-1-ouverture-expliquez-que-vous-apprenez-pas-que-vous-vendez" aria-label="Permalink to “6.1 Ouverture : expliquez que vous apprenez, pas que vous vendez”">​</a></h3><p>Par exemple :</p><blockquote><p>Je fais des recherches sur la façon dont les gens gèrent ce type de problème, je veux d&#39;abord comprendre la situation réelle, je ne viens pas vous vendre quelque chose.</p></blockquote><p>Cette formulation permet à l&#39;autre personne de relâcher plus facilement le fardeau psychologique de « devoir vous donner un retour positif ».</p><h3 id="_6-2-commencez-par-la-derniere-experience-reelle" tabindex="-1">6.2 Commencez par la dernière expérience réelle <a class="header-anchor" href="#_6-2-commencez-par-la-derniere-experience-reelle" aria-label="Permalink to “6.2 Commencez par la dernière expérience réelle”">​</a></h3><p>Vous pouvez commencer par ce type de questions :</p><ul><li>Quand est la dernière fois que vous avez rencontré ce problème ?</li><li>Que s&#39;est-il passé à ce moment-là ?</li><li>Quelle a été votre première réaction pour le gérer ?</li></ul><p>Une fois que la conversation entre dans des événements précis, la qualité des informations s&#39;améliore généralement de manière significative.</p><h3 id="_6-3-approfondissez-sur-les-comportements-les-couts-et-les-alternatives" tabindex="-1">6.3 Approfondissez sur les comportements, les coûts et les alternatives <a class="header-anchor" href="#_6-3-approfondissez-sur-les-comportements-les-couts-et-les-alternatives" aria-label="Permalink to “6.3 Approfondissez sur les comportements, les coûts et les alternatives”">​</a></h3><p>Continuez à demander :</p><ul><li>Comment résolvez-vous ce problème actuellement ?</li><li>Qu&#39;est-ce qui est le plus désagréable dans cette méthode ?</li><li>Combien de temps, d&#39;argent ou d&#39;énergie y consacrez-vous ?</li><li>Avez-vous essayé d&#39;autres méthodes ? Pourquoi ne les avez-vous pas poursuivies ?</li></ul><h3 id="_6-4-enfin-evaluez-la-douleur-et-la-priorite" tabindex="-1">6.4 Enfin, évaluez la douleur et la priorité <a class="header-anchor" href="#_6-4-enfin-evaluez-la-douleur-et-la-priorite" aria-label="Permalink to “6.4 Enfin, évaluez la douleur et la priorité”">​</a></h3><p>Vous n&#39;avez pas besoin de demander directement « est-ce douloureux ? », vous pouvez juger à partir des détails :</p><ul><li>Est-ce que ça arrive souvent</li><li>Est-ce qu&#39;il cherche activement des solutions de secours</li><li>Est-ce qu&#39;il est déjà prêt à payer pour ça</li><li>Est-ce qu&#39;il montre des émotions évidentes quand il en parle</li></ul><p>Tout cela est plus utile qu&#39;une simple « est-ce que c&#39;est votre point de douleur ».</p><h2 id="_7-un-exemple-plus-complet" tabindex="-1">7. Un exemple plus complet <a class="header-anchor" href="#_7-un-exemple-plus-complet" aria-label="Permalink to “7. Un exemple plus complet”">​</a></h2><p>Supposons que vous voulez créer un produit « AI qui aide les étudiants à améliorer leur CV ».</p><h3 id="mauvaise-approche" tabindex="-1">Mauvaise approche <a class="header-anchor" href="#mauvaise-approche" aria-label="Permalink to “Mauvaise approche”">​</a></h3><p>Vous allez demander à des camarades :</p><blockquote><p>Je veux créer un outil d&#39;optimisation de CV par AI, tu en penses quoi ? S&#39;il pouvait adapter automatiquement le CV selon le poste, tu l&#39;utiliserais ?</p></blockquote><p>À ce moment, l&#39;autre personne dira probablement :</p><ul><li>Ça a l&#39;air pas mal</li><li>Je pense que ça pourrait être utile</li></ul><blockquote><p>Si c&#39;est gratuit, j&#39;essaierais</p></blockquote><p>Ces réponses ne vous aident pratiquement pas à déterminer si le besoin est fort ou non.</p><h3 id="meilleure-approche" tabindex="-1">Meilleure approche <a class="header-anchor" href="#meilleure-approche" aria-label="Permalink to “Meilleure approche”">​</a></h3><p>Vous pourriez reformuler :</p><blockquote><p>Quand est la dernière fois que tu as modifié ton CV ? Pourquoi devais-tu le modifier à ce moment-là ? Comment t&#39;y es-tu pris ? Quelle étape t&#39;a le plus bloqué ? As-tu demandé à quelqu&#39;un de t&#39;aider à le relire ? As-tu déjà passé beaucoup de temps ou dépensé de l&#39;argent pour ton CV ?</p></blockquote><p>Grâce à ces questions, les informations que vous pourriez obtenir sont :</p><ul><li>Beaucoup de gens ne savent pas écrire, mais ne savent pas comment adapter leur CV pour différents postes</li><li>Leur plus grande difficulté n&#39;est pas la mise en page, mais « ne pas savoir quelles expériences valent la peine d&#39;être mentionnées »</li><li>Ils procrastinent, pas parce qu&#39;ils sont paresseux, mais parce que chaque modification de CV est épuisante</li><li>Ils utilisent déjà les conseils de leurs aînés, les sites de modèles, les outils AI et les relectures par des amis pour s&#39;en sortir</li></ul><p>À ce stade, vous êtes bien plus proche du problème réel.</p><h2 id="_8-comment-combiner-the-mom-test-avec-jtbd" tabindex="-1">8. Comment combiner The Mom Test avec JTBD <a class="header-anchor" href="#_8-comment-combiner-the-mom-test-avec-jtbd" aria-label="Permalink to “8. Comment combiner The Mom Test avec JTBD”">​</a></h2><p>Si JTBD vous aide à voir « ce que l&#39;utilisateur veut accomplir », The Mom Test vous apprend plutôt :</p><p><strong>Comment vérifier, par des entretiens, si ce job existe vraiment.</strong></p><p>Vous pouvez tout à fait les utiliser ensemble :</p><ol><li>D&#39;abord, utilisez JTBD pour formuler une hypothèse de job</li><li>Puis utilisez les techniques de The Mom Test pour interroger les utilisateurs sur leur dernière expérience réelle</li><li>Vérifiez si ce job est vraiment fréquent, réel et prioritaire</li></ol><p>Par exemple, votre hypothèse JTBD pourrait être :</p><blockquote><p>Quand je prépare ma candidature pour un stage, je veux rapidement adapter mon ancien CV en une version adaptée au poste, pour pouvoir soumettre ma candidature dès que possible.</p></blockquote><p>Vous pouvez alors vérifier avec des questions de style The Mom Test :</p><ul><li>Quand est la dernière fois que tu as postulé ?</li><li>Comment as-tu modifié ton CV à ce moment-là ?</li><li>Quelle partie a été la plus difficile à écrire ?</li><li>Après modification, comment jugerais-tu si c&#39;est assez bon ?</li></ul><p>Ainsi, les méthodes se connectent :</p><ul><li>JTBD vous aide à définir l&#39;hypothèse de besoin</li><li>The Mom Test vous aide à vérifier l&#39;hypothèse par entretien</li></ul><h2 id="_9-erreurs-les-plus-courantes-des-debutants-lors-des-entretiens-utilisateurs" tabindex="-1">9. Erreurs les plus courantes des débutants lors des entretiens utilisateurs <a class="header-anchor" href="#_9-erreurs-les-plus-courantes-des-debutants-lors-des-entretiens-utilisateurs" aria-label="Permalink to “9. Erreurs les plus courantes des débutants lors des entretiens utilisateurs”">​</a></h2><h3 id="_9-1-transformer-l-entretien-en-presentation-produit" tabindex="-1">9.1 Transformer l&#39;entretien en présentation produit <a class="header-anchor" href="#_9-1-transformer-l-entretien-en-presentation-produit" aria-label="Permalink to “9.1 Transformer l&#39;entretien en présentation produit”">​</a></h3><p>Plus vous parlez de vos propres idées, plus l&#39;autre personne aura tendance à vous suivre, au lieu de vous dire la réalité.</p><h3 id="_9-2-n-interroger-que-des-connaissances" tabindex="-1">9.2 N&#39;interroger que des connaissances <a class="header-anchor" href="#_9-2-n-interroger-que-des-connaissances" aria-label="Permalink to “9.2 N&#39;interroger que des connaissances”">​</a></h3><p>Les connaissances ne sont pas interdites, mais elles sont plus enclines à vous encourager. Vous devez au moins mélanger des personnes plus proches des utilisateurs réels, pas seulement des gens qui vous soutiennent.</p><h3 id="_9-3-poser-des-questions-sur-les-fonctionnalites-trop-tot" tabindex="-1">9.3 Poser des questions sur les fonctionnalités trop tôt <a class="header-anchor" href="#_9-3-poser-des-questions-sur-les-fonctionnalites-trop-tot" aria-label="Permalink to “9.3 Poser des questions sur les fonctionnalités trop tôt”">​</a></h3><p>Si vous n&#39;avez pas encore compris le problème, commencer à poser des questions sur les boutons, l&#39;interface et les détails des fonctionnalités, c&#39;est généralement entrer trop tôt dans la solution.</p><h3 id="_9-4-prendre-un-«-je-l-utiliserais-»-pour-un-resultat-de-validation" tabindex="-1">9.4 Prendre un « je l&#39;utiliserais » pour un résultat de validation <a class="header-anchor" href="#_9-4-prendre-un-«-je-l-utiliserais-»-pour-un-resultat-de-validation" aria-label="Permalink to “9.4 Prendre un « je l&#39;utiliserais » pour un résultat de validation”">​</a></h3><p>L&#39;entretien vous aide au mieux à juger la direction, il ne remplace pas la validation. La vraie validation, c&#39;est de voir si les utilisateurs sont prêts à payer un coût réel — temps, coût de changement, essai, voire paiement.</p><h3 id="_9-5-ne-pas-organiser-les-notes-apres-l-entretien" tabindex="-1">9.5 Ne pas organiser les notes après l&#39;entretien <a class="header-anchor" href="#_9-5-ne-pas-organiser-les-notes-apres-l-entretien" aria-label="Permalink to “9.5 Ne pas organiser les notes après l&#39;entretien”">​</a></h3><p>Si vous laissez les informations de côté après avoir discuté, elles deviennent vite des impressions floues. Il vaut mieux les organiser rapidement :</p><ul><li>Les problèmes les plus fréquents</li><li>Les mots émotionnels dans les propos originaux des utilisateurs</li><li>Les solutions alternatives actuelles</li><li>Les coûts déjà engagés</li><li>Vos propres nouveaux jugements</li></ul><h2 id="_10-liste-de-questions-pretes-a-l-emploi" tabindex="-1">10. Liste de questions prêtes à l&#39;emploi <a class="header-anchor" href="#_10-liste-de-questions-pretes-a-l-emploi" aria-label="Permalink to “10. Liste de questions prêtes à l&#39;emploi”">​</a></h2><p>Si vous voulez commencer rapidement, voici un ensemble de questions suffisamment polyvalentes.</p><h3 id="questions-d-ouverture" tabindex="-1">Questions d&#39;ouverture <a class="header-anchor" href="#questions-d-ouverture" aria-label="Permalink to “Questions d&#39;ouverture”">​</a></h3><ul><li>Quand est la dernière fois que vous avez rencontré ce problème ?</li><li>Que s&#39;est-il passé exactement à ce moment-là ?</li></ul><h3 id="questions-sur-les-comportements" tabindex="-1">Questions sur les comportements <a class="header-anchor" href="#questions-sur-les-comportements" aria-label="Permalink to “Questions sur les comportements”">​</a></h3><ul><li>Comment avez-vous géré la situation à ce moment-là ?</li><li>Pourquoi avez-vous choisi cette méthode ?</li></ul><h3 id="questions-sur-les-couts" tabindex="-1">Questions sur les coûts <a class="header-anchor" href="#questions-sur-les-couts" aria-label="Permalink to “Questions sur les coûts”">​</a></h3><ul><li>Combien de temps ou d&#39;énergie cette tâche vous prend-elle généralement ?</li><li>Avez-vous déjà dépensé de l&#39;argent pour la résoudre ?</li></ul><h3 id="questions-sur-les-alternatives" tabindex="-1">Questions sur les alternatives <a class="header-anchor" href="#questions-sur-les-alternatives" aria-label="Permalink to “Questions sur les alternatives”">​</a></h3><ul><li>Avez-vous essayé d&#39;autres outils ou méthodes ?</li><li>Pourquoi ne les avez-vous pas continués ?</li></ul><h3 id="questions-de-cloture" tabindex="-1">Questions de clôture <a class="header-anchor" href="#questions-de-cloture" aria-label="Permalink to “Questions de clôture”">​</a></h3><ul><li>Si vous rencontrez le même problème à l&#39;avenir, à quoi ressemblerait la solution idéale ?</li></ul><p>Notez que cette question de clôture peut être posée, mais il vaut mieux la garder pour la fin. Parce que vous avez d&#39;abord besoin de recueillir des faits, pas des souhaits.</p><h2 id="_11-resume" tabindex="-1">11. Résumé <a class="header-anchor" href="#_11-resume" aria-label="Permalink to “11. Résumé”">​</a></h2><p>La contribution la plus importante de The Mom Test n&#39;est pas de vous donner une technique pour « mieux discuter », mais de vous aider à construire un mode de jugement plus lucide :</p><ul><li>Ne croyez pas trop vite aux compliments des autres sur vos idées</li><li>Ne prenez pas « si ça existait, je l&#39;utiliserais » pour un besoin réel</li><li>Ne transformez pas vos entretiens en quête de validation</li></ul><p>Un entretien véritablement précieux devrait revenir autant que possible à ces éléments :</p><ul><li>La dernière expérience réelle de l&#39;utilisateur</li><li>Comment il gère le problème actuellement</li><li>Ce qu&#39;il a déjà payé</li><li>Où il est visiblement mal à l&#39;aise</li></ul><p>Quand vous commencez à poser les questions de cette façon, les informations que vous obtiendrez seront parfois moins flatteuses, mais généralement plus utiles. Et quand on crée un produit, <strong>une vérité utile est toujours plus importante qu&#39;un encouragement flatteur.</strong></p><p><a id="mom-ai"></a></p><h2 id="_12-comment-utiliser-l-ia-pour-vos-entretiens-utilisateurs" tabindex="-1"><a href="#top-mom">12. Comment utiliser l&#39;IA pour vos entretiens utilisateurs</a> <a class="header-anchor" href="#_12-comment-utiliser-l-ia-pour-vos-entretiens-utilisateurs" aria-label="Permalink to “12. Comment utiliser l&#39;IA pour vos entretiens utilisateurs”">​</a></h2><p>The Mom Test est fondamentalement une méthode pour « discuter avec de vraies personnes », l&#39;IA ne peut donc pas remplacer les entretiens réels. Mais l&#39;IA est très utile comme assistante avant, pendant et après les entretiens, surtout pour réduire la barrière d&#39;entrée des débutants.</p><h3 id="_12-1-laissez-l-ia-reecrire-vos-questions-«-faciles-a-rater-»" tabindex="-1">12.1 Laissez l&#39;IA réécrire vos questions « faciles à rater » <a class="header-anchor" href="#_12-1-laissez-l-ia-reecrire-vos-questions-«-faciles-a-rater-»" aria-label="Permalink to “12.1 Laissez l&#39;IA réécrire vos questions « faciles à rater »”">​</a></h3><p>Beaucoup de gens savent qu&#39;ils ne devraient pas demander « tu penses quoi de mon idée », mais à la première occasion, ils reviennent à ce type de phrase. Vous pouvez d&#39;abord confier vos questions préparées à l&#39;IA pour qu&#39;elle les réécrive :</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Voici les questions que je prépare pour des entretiens utilisateurs :</span></span>
<span class="line"><span>[insérez vos questions]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Merci de les réécrire selon les principes de The Mom Test :</span></span>
<span class="line"><span>1. Supprimez les questions d&#39;opinion</span></span>
<span class="line"><span>2. Supprimez les questions qui supposent l&#39;avenir</span></span>
<span class="line"><span>3. Reformulez-les autant que possible autour des comportements passés réels, des alternatives existantes et des coûts déjà engagés</span></span>
<span class="line"><span>4. Organisez le tout en une liste de 8 à 10 questions prêtes pour l&#39;entretien</span></span></code></pre></div><p>Même une entrée très basique fonctionne :</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Je veux demander aux utilisateurs :</span></span>
<span class="line"><span>1. Tu penses quoi de mon idée d&#39;outil AI pour améliorer les CV ?</span></span>
<span class="line"><span>2. Tu l&#39;utiliserais ?</span></span>
<span class="line"><span>3. Serais-tu prêt à payer ?</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Aide-moi à reformuler ces questions.</span></span></code></pre></div><p>L&#39;IA pourrait produire quelque chose comme :</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Questions réécrites :</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Quand est la dernière fois que tu as modifié ton CV ?</span></span>
<span class="line"><span>2. Pourquoi devais-tu le modifier ?</span></span>
<span class="line"><span>3. Comment t&#39;y es-tu pris ?</span></span>
<span class="line"><span>4. Quelle étape t&#39;a pris le plus de temps ?</span></span>
<span class="line"><span>5. As-tu demandé à quelqu&#39;un de t&#39;aider à le relire ?</span></span>
<span class="line"><span>6. As-tu déjà passé beaucoup de temps ou dépensé de l&#39;argent pour modifier ton CV ?</span></span></code></pre></div><p>Ce type de résultat est très utile parce qu&#39;il transforme directement vos questions « demandant des opinions » en questions « demandant des comportements réels ».</p><h3 id="_12-2-laissez-l-ia-generer-des-guides-d-entretien-pour-differents-profils" tabindex="-1">12.2 Laissez l&#39;IA générer des guides d&#39;entretien pour différents profils <a class="header-anchor" href="#_12-2-laissez-l-ia-generer-des-guides-d-entretien-pour-differents-profils" aria-label="Permalink to “12.2 Laissez l&#39;IA générer des guides d&#39;entretien pour différents profils”">​</a></h3><p>Pour un même domaine, face à différents publics, l&#39;accent de l&#39;entretien sera différent. Par exemple, les étudiants, les RH, les travailleurs indépendants ont des préoccupations complètement différentes. Vous pouvez demander à l&#39;IA de générer une version de guide pour chaque type d&#39;interlocuteur :</p><ul><li>Pour les utilisateurs débutants, concentrez-vous sur la dernière expérience réelle</li><li>Pour les utilisateurs intensifs, concentrez-vous sur les alternatives et la douleur</li><li>Pour les utilisateurs payants, concentrez-vous sur les coûts déjà engagés</li></ul><p>Ainsi, vous aurez un meilleur rythme lors des vraies conversations, au lieu de poser les mêmes questions à tout le monde.</p><p>Par exemple, vous pouvez saisir directement :</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Je vais discuter avec deux types de personnes :</span></span>
<span class="line"><span>1. Étudiants qui cherchent leur premier stage</span></span>
<span class="line"><span>2. Étudiants plus avancés qui ont déjà relu beaucoup de CV</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Donnez-moi un guide d&#39;entretien pour chacun, 6 questions par guide.</span></span></code></pre></div><p>L&#39;IA pourrait générer :</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Pour les étudiants :</span></span>
<span class="line"><span>1. Quand est la dernière fois que tu as postulé pour un stage ?</span></span>
<span class="line"><span>2. Quelle étape t&#39;a le plus bloqué ?</span></span>
<span class="line"><span>3. Comment sais-tu si ton CV est prêt à être envoyé ?</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Pour les étudiants avancés :</span></span>
<span class="line"><span>1. Quand est la dernière fois que tu as aidé quelqu&#39;un à relire son CV ?</span></span>
<span class="line"><span>2. Quels problèmes évidents vois-tu le plus souvent ?</span></span>
<span class="line"><span>3. À quelle étape les plus jeunes bloquent-ils le plus ?</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>Ainsi, vous n&#39;avez pas besoin d&#39;inventer les questions à partir de zéro, la préparation de l&#39;entretien sera beaucoup plus facile.</p><h3 id="_12-3-laissez-l-ia-organiser-vos-notes-d-entretien" tabindex="-1">12.3 Laissez l&#39;IA organiser vos notes d&#39;entretien <a class="header-anchor" href="#_12-3-laissez-l-ia-organiser-vos-notes-d-entretien" aria-label="Permalink to “12.3 Laissez l&#39;IA organiser vos notes d&#39;entretien”">​</a></h3><p>Après les entretiens, le problème le plus fréquent n&#39;est pas « manquer d&#39;informations », mais « les informations sont trop dispersées ». L&#39;IA est très adaptée pour vous aider à organiser des conversations fragmentées en notes structurées :</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Voici les notes de mes entretiens avec 3 utilisateurs.</span></span>
<span class="line"><span>Merci de les organiser selon la perspective de The Mom Test :</span></span>
<span class="line"><span>1. Quels contenus sont des faits, lesquels sont juste des opinions</span></span>
<span class="line"><span>2. Quel est le dernier comportement réel de l&#39;utilisateur</span></span>
<span class="line"><span>3. Quelle est la solution alternative actuelle</span></span>
<span class="line"><span>4. Quels sont les coûts en temps, argent ou énergie déjà engagés par l&#39;utilisateur</span></span>
<span class="line"><span>5. Quels problèmes ont été mentionnés à plusieurs reprises</span></span>
<span class="line"><span>6. Quelles déclarations semblent positives mais manquent de preuves</span></span></code></pre></div><p>Cette étape est particulièrement précieuse car elle vous aide à séparer le contenu « qui a l&#39;air pas mal » du contenu « qui peut vraiment étayer vos décisions ».</p><p>Une entrée simple pourrait être :</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Voici les notes après une conversation avec un utilisateur :</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- Elle a dit que si un outil existait, elle essaierait probablement</span></span>
<span class="line"><span>- La semaine dernière, elle a passé une soirée entière à modifier son CV</span></span>
<span class="line"><span>- Actuellement, elle demande principalement à des amis de l&#39;aider à relire</span></span>
<span class="line"><span>- Elle a dit que le plus difficile est de savoir quand un CV est « prêt à être envoyé »</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Aidez-moi à distinguer ce qui est opinion et ce qui est fait.</span></span></code></pre></div><p>L&#39;IA pourrait répondre :</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Opinions :</span></span>
<span class="line"><span>- Si un outil existait, elle essaierait probablement</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Faits :</span></span>
<span class="line"><span>- La semaine dernière, elle a passé une soirée à modifier son CV</span></span>
<span class="line"><span>- La solution alternative actuelle est de demander à des amis de relire</span></span>
<span class="line"><span>- Le point le plus difficile est de savoir quand on peut considérer le CV « prêt à envoyer »</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Points clés pour évaluer le besoin :</span></span>
<span class="line"><span>- Ce problème est survenu récemment</span></span>
<span class="line"><span>- L&#39;utilisateur a déjà investi un temps significatif</span></span>
<span class="line"><span>- La solution actuelle dépend d&#39;autres personnes, elle n&#39;est pas stable</span></span></code></pre></div><p>Ce résultat montre très intuitivement aux débutants : quelles phrases peuvent servir à prendre des décisions, et lesquelles ne sont que des commentaires.</p><h3 id="_12-4-laissez-l-ia-faire-une-premiere-recherche-en-ligne-legere" tabindex="-1">12.4 Laissez l&#39;IA faire une première recherche en ligne légère <a class="header-anchor" href="#_12-4-laissez-l-ia-faire-une-premiere-recherche-en-ligne-legere" aria-label="Permalink to “12.4 Laissez l&#39;IA faire une première recherche en ligne légère”">​</a></h3><p>Si vous n&#39;avez pas encore commencé vos entretiens, vous pouvez d&#39;abord demander à l&#39;IA de faire une recherche externe très légère, comme :</p><ul><li>Dans les communautés publiques, comment les gens se plaignent-ils de ce problème récemment</li><li>Qu&#39;est-ce qui est le plus critiqué dans les outils existants</li><li>Les utilisateurs ont-ils déjà payé pour des problèmes similaires</li><li>Quelles alternatives existent déjà sur le marché</li></ul><p>Ce type d&#39;information ne remplace pas les entretiens avec de vraies personnes, mais peut vous aider à entrer plus rapidement dans le sujet et à savoir par où commencer les questions.</p><p>Par exemple, une entrée simple pourrait être :</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Merci de rechercher :</span></span>
<span class="line"><span>« Ce dont les étudiants se plaignent le plus quand ils modifient leur CV »</span></span>
<span class="line"><span>Organisez les 5 plaintes les plus fréquentes, dans un langage très simple.</span></span></code></pre></div><p>L&#39;IA pourrait répondre :</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Plaintes fréquentes :</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Ne sait pas ce qu&#39;il faut mettre dans le CV</span></span>
<span class="line"><span>2. Devoir le modifier pour chaque poste, c&#39;est fatigant</span></span>
<span class="line"><span>3. Après de nombreuses modifications, on n&#39;est toujours pas sûr que c&#39;est bien</span></span>
<span class="line"><span>4. Personne ne peut donner un retour fiable</span></span>
<span class="line"><span>5. On a toujours l&#39;impression de ne pas être prêt, donc on remet à plus tard</span></span></code></pre></div><p>La valeur de ce type de résultat est qu&#39;il vous permet de trouver plus facilement un angle d&#39;attaque pour vos entretiens.</p><h3 id="_12-5-laissez-l-ia-jouer-le-role-de-«-coach-de-debriefing-d-entretien-»" tabindex="-1">12.5 Laissez l&#39;IA jouer le rôle de « coach de débriefing d&#39;entretien » <a class="header-anchor" href="#_12-5-laissez-l-ia-jouer-le-role-de-«-coach-de-debriefing-d-entretien-»" aria-label="Permalink to “12.5 Laissez l&#39;IA jouer le rôle de « coach de débriefing d&#39;entretien »”">​</a></h3><p>Vous pouvez aussi confier les notes d&#39;un entretien que vous venez de terminer à l&#39;IA, et lui demander de vous faire des critiques :</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Voici les notes d&#39;un entretien utilisateur que je viens de faire.</span></span>
<span class="line"><span>Merci de m&#39;aider à débriefé depuis la perspective de The Mom Test :</span></span>
<span class="line"><span>1. Quelles questions ressemblaient trop à une recherche de validation</span></span>
<span class="line"><span>2. Quelles questions étaient trop orientées</span></span>
<span class="line"><span>3. Où aurais-je pu approfondir sur les faits</span></span>
<span class="line"><span>4. Si je pouvais recommencer, comment pourrais-je mieux poser les questions dans cette conversation</span></span></code></pre></div><p>C&#39;est particulièrement utile pour les débutants, car vous développerez plus rapidement une sensibilité à « est-ce que je collecte des preuves ou des encouragements ».</p><h2 id="📚-exercices" tabindex="-1">📚 Exercices <a class="header-anchor" href="#📚-exercices" aria-label="Permalink to “📚 Exercices”">​</a></h2><p>En vous basant sur le contenu ci-dessus, veuillez réaliser les exercices suivants :</p><ol><li>Choisissez un produit que vous voulez créer récemment, et écrivez d&#39;abord 5 questions « faciles à rater » que vous auriez posées</li><li>Réécrivez ces 5 questions dans un style plus conforme à The Mom Test</li><li>Trouvez 3 utilisateurs potentiels, et posez au moins une fois « quand est la dernière fois que vous avez rencontré ce problème »</li><li>Après l&#39;entretien, organisez 4 types d&#39;informations : comportements réels, alternatives, coûts engagés, difficultés récurrentes</li></ol><h2 id="lectures-complementaires" tabindex="-1">Lectures complémentaires <a class="header-anchor" href="#lectures-complementaires" aria-label="Permalink to “Lectures complémentaires”">​</a></h2><ul><li><a href="https://momtestbook.com/" target="_blank" rel="noreferrer">Site officiel de The Mom Test</a></li><li><a href="https://www.robfitz.com/the-mom-test/" target="_blank" rel="noreferrer">Rob Fitzpatrick : The Mom Test</a></li></ul>`,186))])}}});export{v as __pageData,b as default};
